class DailyMasterSchedule():
    """Object Model for the Schedule > Daily Master... window.

    A SEPARATE dialog from the Location Schedule, despite looking alike: every control id
    differs (table 16435 vs 16428, Close/Add/Change 16436/16437/16438 vs 16429/16430/16431), and
    it is scoped by a Department dropdown rather than a Location textbox. Reusing the
    ScheduleLocation maps here would drive the wrong window whenever both are open, so each
    control below is anchored to ui_Main_Window and matched on its caption where it has one.

    Verified against MOSAIQ with my-test-scripts/inspect_daily_master_schedule.py; the window
    caption reads " <date>  <DAY> - Daily Master Schedule: <department>".
    """
    ui_Main_Window = {"text": objectmaphelper.Wildcard("*Daily Master Schedule*")}

    window_Table_Pane = {"container": ui_Main_Window, "id": 16435, "type": "Pane"}
    window_Department_Dropdown = {"container": ui_Main_Window, "text": "Department:", "type": "Pane"}

    # Row counter, rendered "<selected> / <total>". The table itself is a ClaList that publishes
    # nothing but scrollbars, so this counter is the only way to size the day's schedule without
    # OCR. Pane 16447 mirrors the same value. Anchored to ui_Main_Window and typed Pane because
    # id 16445 is the Location textbox -- an Edit -- over in the Location Schedule dialog.
    window_Row_Counter_Pane = {"container": ui_Main_Window, "id": 16445, "type": "Pane"}

    window_Close_Button = {"container": ui_Main_Window, "text": "Close", "type": "Button"}
    window_Add_Button = {"container": ui_Main_Window, "text": "Add", "type": "Button"}
    window_Change_Button = {"container": ui_Main_Window, "text": "Change", "type": "Button"}
    window_Delete_Button = {"container": ui_Main_Window, "text": "Delete", "type": "Button"}
    window_Refresh_Button = {"container": ui_Main_Window, "text": "Refresh", "type": "Button"}


